/// <summary>
///     replaces reference lookup for personalTitle in AVADirPerson
/// </summary>
/// <param name="sender">
///    <c>FormControl</c> as type
/// </param>
/// <param name="e">
///    <c>FormControlEventArgs</c> as type
/// </param>
[FormControlEventHandler(formControlStr(DirPartyQuickCreateForm, DirPartyTable_DirPerson_PersonalTitle), FormControlEventType::Lookup)]
public static void DirPartyTable_DirPerson_PersonalTitle_OnLookup(FormControl sender, FormControlEventArgs e)
{
    FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;

    DirUtility::buildAffixReferenceControlLookup(sender, DirNameAffixType::PersonalPrefix);

    ce.CancelSuperCall();
}
